const allItems = $input.all();

// ── Find each item by its content signature ──────────────────────────
const webhookItem    = allItems.find(item => item.json.body?.document_text || item.json.document_text);
const extractionItem = allItems.find(item => item.json.choices?.[0]?.message?.content?.includes('client_name'));
const riskItem       = allItems.find(item => item.json.choices?.[0]?.message?.content?.includes('risk_level'));

if (!webhookItem)    throw new Error("No webhook item found in merge. Check Merge node has 3 inputs.");
if (!extractionItem) throw new Error("No extraction response found. Check extraction agent.");
if (!riskItem)       throw new Error("No risk response found. Check Risk Scoring agent.");

// ── Parse LM Studio responses ─────────────────────────────────────────
function getContent(item) {
  const msg = item.json.choices[0].message;
  return msg.content || msg.reasoning_content || "";
}

function extractJSON(str) {
  const match = str.match(/\{[\s\S]*\}/);
  if (match) return JSON.parse(match[0]);
  throw new Error("No JSON found. Raw: " + str.substring(0, 200));
}

const extracted = extractJSON(getContent(extractionItem));
const riskData   = extractJSON(getContent(riskItem));

// ── Normalise document_type to canonical short form ───────────────────
const typeNormMap = {
  'formal correspondence':                                'correspondence',
  'draft internal notes':                                 'internal_notes',
  'payment voucher and receipt for raw timber materials': 'payment voucher and receipt',
  'monthly account statement':                            'monthly account statement',
  'monthly_account_statement':                            'monthly account statement',
  'out-of-court settlement deed':                         'out-of-court settlement deed',
  'settlement deed':                                      'settlement deed',
};
const rawType = (extracted.document_type || '').toLowerCase().trim();
extracted.document_type = typeNormMap[rawType] || extracted.document_type;

// ── Pull webhook fields ───────────────────────────────────────────────
const docText       = webhookItem.json.body?.document_text || webhookItem.json.document_text || extracted.summary || "";
const csvClientName = webhookItem.json.body?.client_name  || webhookItem.json.client_name   || extracted.client_name || "—";

// ── Rule-based risk scoring ───────────────────────────────────────────
function calculateRisk(extracted, docText) {
  const text   = (docText || "").toLowerCase();
  const amount = parseFloat(((extracted && extracted.amount) || "0").replace(/[^0-9.-]/g, ""));

  if (
    text.includes("cash")                  ||
    text.includes("miscellaneous")         ||
    text.includes("48 hour")              ||
    text.includes("24 hour")              ||
    text.includes("no vat")               ||
    text.includes("first transaction")    ||
    text.includes("no supporting")        ||
    text.includes("settlement")           ||
    text.includes("critical pages missing")||
    text.includes("incomplete document")  ||
    Math.abs(amount) > 50000
  ) return { risk_level: "high", risk_reason: "Suspicious patterns detected — cash payment, vague description, missing documentation, incomplete document, or high value settlement.", requires_review: true };

  if (Math.abs(amount) > 10000 || text.includes("no itemised") || text.includes("missing fields")) {
    return { risk_level: "medium", risk_reason: "Amount over £10,000 or incomplete documentation.", requires_review: true };
  }

  return { risk_level: "low", risk_reason: "Routine document within normal parameters.", requires_review: false };
}

const ruleRisk = calculateRisk(extracted, docText);
const llmRiskLevel = (riskData.risk_level || "low").toLowerCase().trim();

// ── Compare rule-based vs LLM risk — escalate if they disagree ────────
let risk;
const riskOrder = { low: 0, medium: 1, high: 2 };

if (llmRiskLevel === 'high' && ruleRisk.risk_level !== 'high') {
  // LLM sees high risk but rules don't — escalate and flag disagreement
  risk = {
    risk_level:      "high",
    risk_reason:     "AI risk assessment flagged HIGH — " + (riskData.risk_reason || "see AI assessment") + " (Rule engine: " + ruleRisk.risk_level + ")",
    requires_review: true
  };
} else if (ruleRisk.risk_level === 'high' && llmRiskLevel !== 'high') {
  // Rules see high risk but LLM doesn't — trust rules, note disagreement
  risk = {
    risk_level:      "high",
    risk_reason:     ruleRisk.risk_reason + " (Note: AI assessed as " + llmRiskLevel + " — rule engine override)",
    requires_review: true
  };
} else {
  // Both agree — use rule-based result as authoritative
  risk = ruleRisk;
}
// ── Validation ────────────────────────────────────────────────────────
const errors = [];
const validTypes = [
  "invoice", "statement", "letter", "form", "report", "unknown",
  "internal_notes", "draft internal notes", "payment voucher",
  "payment voucher and receipt", "receipt", "contract", "memo",
  "correspondence", "monthly account statement",
  "out-of-court settlement deed", "settlement deed"
];

if (!csvClientName || csvClientName.trim() === "" || csvClientName === "—") errors.push("Missing client name");
if (!validTypes.includes(extracted.document_type?.toLowerCase()))              errors.push("Invalid document type: " + extracted.document_type);
if (!extracted.document_date || extracted.document_date === "—")               errors.push("Missing document date");
if (extracted.document_type?.toLowerCase() === "invoice" && !extracted.amount) errors.push("Invoice must have a positive amount");
if (!extracted.summary)                                                         errors.push("Missing summary");

const status = errors.length === 0 ? "PASS" : "FAIL";

// ── Output ────────────────────────────────────────────────────────────
return [{
  json: {
    document_id:       webhookItem.json.body?.document_id || webhookItem.json.document_id || 'DOC-' + Date.now(),
    client_name:       csvClientName,
    document_type:     extracted.document_type  || "—",
    document_date:     extracted.document_date  || "—",
    amount:            extracted.amount         || "—",
    summary:           extracted.summary        || "—",
    risk_level:        risk.risk_level,
    risk_reason:       risk.risk_reason,
    requires_review:   risk.requires_review === true ? "Yes" : "No",
    validation_status: status,
    errors:            errors.join(", "),
    timestamp:         new Date().toISOString()
  }
}];

