const input = $input.first().json;

// document_text may be at json.body.document_text or json.document_text
const raw = input.body || input;

const sanitised = (raw.document_text || '')
  .replace(/\\/g, '\\\\')
  .replace(/"/g, '\\"')
  .replace(/\n/g, '\\n')
  .replace(/\r/g, '\\r')
  .replace(/\t/g, '\\t');

return [{
  json: {
    body: {
      document_text: sanitised,
      client_name:   raw.client_name  || '',
      document_id:   raw.document_id  || '',
      model_name:    raw.model_name   || '',
      lm_studio_url: raw.lm_studio_url || ''
    }
  }
}];

const token = $input.first().json.headers['x-api-key'];
const validToken = 'dia-secret-2026';

if (!token || token !== validToken) {
  throw new Error('Unauthorised: invalid or missing x-api-key header');
}

return $input.all();

const allItems = $input.all();

// Check extraction response exists and has choices
const extractionItem = allItems.find(item => item.json.choices?.[0]?.message?.content);
const riskItem = allItems.find(item => item.json.choices?.[0]?.message?.content?.includes('risk_level'));

if (!extractionItem) {
  return [{
    json: {
      error: true,
      error_message: "Extraction agent failed — LM Studio may be down or returned malformed response",
      document_id: 'ERR-' + Date.now(),
      client_name: "—",
      document_type: "—",
      document_date: "—",
      amount: "—",
      summary: "—",
      risk_level: "unknown",
      risk_reason: "Pipeline error — manual review required",
      requires_review: "Yes",
      validation_status: "ERROR",
      errors: "LM Studio extraction failed",
      timestamp: new Date().toISOString()
    }
  }];
}

if (!riskItem) {
  return [{
    json: {
      error: true,
      error_message: "Risk scoring agent failed — LM Studio may be down or returned malformed response",
      document_id: 'ERR-' + Date.now(),
      client_name: "—",
      document_type: "—",
      document_date: "—",
      amount: "—",
      summary: "—",
      risk_level: "unknown",
      risk_reason: "Pipeline error — manual review required",
      requires_review: "Yes",
      validation_status: "ERROR",
      errors: "LM Studio risk scoring failed",
      timestamp: new Date().toISOString()
    }
  }];
}

return allItems;

const data = $input.first().json;

// Determine why it was flagged
let flag_reason = [];
if (data.validation_status === 'FAIL') flag_reason.push('Validation failed');
if (data.risk_level === 'high') flag_reason.push('HIGH risk score');
if (data.requires_review === 'Yes') flag_reason.push('Review required');
if (data.risk_reason && data.risk_reason.includes('rule engine override')) {
  flag_reason.push('Risk system disagreement');
}

return [{
  json: {
    ...data,
    flag_reason: flag_reason.join(', ')
  }
}];

const rows = $input.all();

const highRisk = rows
  .filter(item => (item.json.risk_level || '').toLowerCase() === 'high')
  .slice(-20)
  .map(item => ({
    client_name:   item.json.client_name   || '',
    document_type: item.json.document_type || '',
    amount:        item.json.amount        || '',
    risk_reason:   item.json.risk_reason   || '',
    summary:       item.json.summary       || ''
  }));

return [{ json: { high_risk_history: highRisk } }];

const allItems = $input.all();

const webhookData = allItems.find(item => item.json.body?.query || item.json.query);
const query = webhookData?.json.body?.query || webhookData?.json.query || 'Show all high risk documents';

const auditRows = allItems
  .filter(item => item.json.document_id)
  .slice(-30)
  .map(item =>
    `ID: ${item.json.document_id} | Client: ${item.json.client_name} | Type: ${item.json.document_type} | Amount: ${item.json.amount} | Risk: ${item.json.risk_level} | Status: ${item.json.validation_status}`
  );

const userContent = 'Audit log data:\n' + auditRows.join('\n') + '\n\nQuestion: ' + query + '\n\nAnswer concisely with specific document IDs where relevant.';

return [{
  json: {
    model: 'qwen2.5-coder-7b-instruct',
    temperature: 0.2,
    max_tokens: 500,
    messages: [
      {
        role: 'system',
        content: 'You are an audit data analyst. Answer questions about document audit logs accurately and concisely. Reference specific document IDs in your answers.'
      },
      {
        role: 'user',
        content: userContent
      }
    ]
  }
}];
